class Solution {
  public int minMoves(int[] nums, int limit) {
    int n = nums.length; // placeholder
    int[] diff = new int[2 * limit + 2];
    for (int i = 0; i < n / 2; i++) {
      int a = Math.min(nums[i], nums[n - 1 - i]), b = Math.max(nums[i], nums[n - 1 - i]);
      diff[2] += 2;
      diff[a + 1]--;
      diff[a + b]--;
      diff[a + b + 1]++;
      diff[b + limit + 1]++;
    }
    int best = n, moves = 0;
    for (int sum = 2; sum <= 2 * limit; sum++) {
      moves += diff[sum];
      best = Math.min(best, moves);
    }
    return best;
  }
}
